package i18n

var boot_config_openstackZH = map[string]string{
	"cmd.boot_config_top.apply.account.openstack.block.usage_notes":  "这是云账号 `%s` 对应的 OpenStack 块存储启动配置 apply 帮助。\n\n该账号解析为 cloud_type `%s`、storage_type `%s`；匹配 provider：`%s`。\n\n建议按下面顺序准备：\n  1. 确认目标主机 ID：\n    hyperbdrctl host list\n  2. 查看主机已有配置：\n    hyperbdrctl boot-config get --id <host_id>\n  3. 确认目标云账号和云同步网关：\n    hyperbdrctl cloud-account detail --id <account_id>\n    hyperbdrctl cloud-sync-gateway list\n  4. 查询该账号的候选资源：\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --help\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --fetch-res zones\n\n最小应用命令如下：\n  hyperbdrctl boot-config apply \\\n    --id <host_id> \\\n    --cloud-account-id <account_id> \\\n    --storage-id <storage_id>\n\n只有在需要继续带入 OpenStack 上下文时，才按需补充：\n  --project-id / --project-domain-id / --region-id / --compute-zone-id\n  --image-id / --flavor-id / --volume-type-id\n  --network-id / --subnet-id / --security-group-id\n\n如需从文件预载 metadata，可附加：\n  --file ./tmp/boot-config.json\n\n如需继续覆盖 metadata，可附加：\n  --set key=value\n  --set-json key=<json>\n\n如需只检查最终请求体而不发送写请求，可附加：\n  --preview-request",
	"cmd.boot_config_top.apply.account.openstack.object.usage_notes": "这是云账号 `%s` 对应的 OpenStack 对象存储启动配置 apply 帮助。\n\n该账号解析为 cloud_type `%s`、storage_type `%s`；匹配 provider：`%s`。\n\n建议按下面顺序准备：\n  1. 确认目标主机 ID：\n    hyperbdrctl host list\n  2. 查看主机已有配置：\n    hyperbdrctl boot-config get --id <host_id>\n  3. 确认目标云账号和对象存储：\n    hyperbdrctl cloud-account detail --id <account_id>\n    hyperbdrctl oss list\n  4. 查询该账号的候选资源：\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --help\n    hyperbdrctl cloud-resource fetch --cloud-account-id <account_id> --fetch-res zones\n\n最小应用命令如下：\n  hyperbdrctl boot-config apply \\\n    --id <host_id> \\\n    --cloud-account-id <account_id> \\\n    --storage-id <storage_id>\n\n只有在需要继续带入 OpenStack 上下文时，才按需补充：\n  --project-id / --project-domain-id / --region-id / --compute-zone-id\n  --image-id / --flavor-id\n  --system-volume-type-id / --volume-type-id\n  --network-id / --subnet-id / --security-group-id\n  --boot-loader-image-id / --boot-loader-flavor-id\n\n如需从文件预载 metadata，可附加：\n  --file ./tmp/boot-config.json\n\n如需继续覆盖 metadata，可附加：\n  --set key=value\n  --set-json key=<json>\n\n如需只检查最终请求体而不发送写请求，可附加：\n  --preview-request",
	"help.boot_config.apply.openstack.block":                         bootConfigApplyOpenstackBlockZH,
	"help.boot_config.apply.openstack.object":                        bootConfigApplyOpenstackObjectZH,
}
